{
  "title": "The Mirror Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver surfaces in a ruined plaza.",
      "visual_description": "A cracked fountain in a destroyed square, with the glass diver emerging from a broken mirror puddle, helmet reflecting shattered towers.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the Cartographer unrolls a wet map.",
      "visual_description": "Under a collapsed archway, Mara spreads a soggy parchment map, her compass dangling, the path to the castle gates marked in faded ink.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp flickers a warning.",
      "visual_description": "Inside a ruined chapel, the Oracle Lamp sits on an altar, its single flame eye casting long shadows, whispering of traps ahead.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The Sleeping Tax Collector snores by the gate.",
      "visual_description": "Before the massive iron castle gates, the Sleeping Tax Collector dozes atop a stack of ledgers, stamped papers stuck to his sleeves.",
      "characters": ["sleeping_tax_collector", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The Tin Fox scouts the gate mechanism.",
      "visual_description": "The small metal fox sniffs the rusted gears of the gate, its key-wind tail ticking, blue glass eyes reflecting the setting sun.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 6,
      "caption": "The group finds old royal banners in the courtyard.",
      "visual_description": "A desolate courtyard littered with faded banners bearing a forgotten crest, tattered fabric swaying in a cold wind.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "Frightened townspeople flee through the streets.",
      "visual_description": "A narrow alley where shadows of frightened townspeople (unregistered) run past, their faces hidden, the glass diver steps aside.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Mara deciphers a cursed tower's rune.",
      "visual_description": "At the base of a twisted stone tower covered in glowing runes, Mara holds her compass, the needle spinning wildly.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "The Oracle Lamp reveals a false door.",
      "visual_description": "The lamp's flame eye illuminates a stone wall, showing the outline of a hidden magic door shimmering with illusion.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "Armored patrols march through the ruins.",
      "visual_description": "From a rooftop, the group watches a column of armored figures (unregistered) marching below, their armor clanking in unison.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "The Tin Fox triggers a pressure plate.",
      "visual_description": "In a dark corridor, the tin fox steps on a loose stone, and a wall of spears shoots out, barely missing the group.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "The Sleeping Tax Collector wakes to stamp a permit.",
      "visual_description": "The tax collector rouses, stamps a random paper, mumbles 'approved,' and falls back asleep, blocking a door.",
      "characters": ["sleeping_tax_collector", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "The Glass Diver swims through a mirror pool.",
      "visual_description": "A shattered mirror in a grand hall becomes a liquid portal; the glass diver leaps in and emerges on the other side of a locked door.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "Mara reads a map of the sky above a dome.",
      "visual_description": "Inside a collapsed observatory, Mara holds her map to a hole in the dome, stars aligning with the drawn constellations.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The Oracle Lamp warns of a collapse.",
      "visual_description": "The lamp's flame flickers red, and the floor begins to crack, the group running as stone slabs fall into a chasm.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The Sleeping Tax Collector blocks the exit.",
      "visual_description": "At the final bridge, the tax collector sits with his ledgers, demanding a toll in his sleep, blocking the way.",
      "characters": ["sleeping_tax_collector", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 17,
      "caption": "The Tin Fox distracts the armored patrols.",
      "visual_description": "The tin fox winds its tail and scampers into a guardhouse, causing a loud clatter, drawing away the armored patrols from the bridge.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 18,
      "caption": "The group escapes across the bridge.",
      "visual_description": "The glass diver, Mara, and the Oracle Lamp cross a crumbling stone bridge over a misty chasm, the city ruins behind them.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    }
  ]
}

